namespace Paramore.Brighter.RMQ.Async.Tests.MessagingGateway.NativeQuorum.Reactor;

/// <summary>
/// An unacceptable message goes to the invalid-message channel and not the dead-letter queue; the
/// absence is checked with one bounded receive, since a poll could only wait out its ceiling.
/// </summary>
[Property("Category", "RMQNativeDelay")]
[NotInParallel("RMQNativeDelay")]
public class WhenRejectingMessageWithUnacceptableReasonShouldSendToInvalidChannel : IDisposable
{
    private readonly IAmAMessageGatewayReactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.RMQ.Async.RmqSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.RMQ.Async.RmqPublication? _publication;

    private IAmAMessageProducerSync? _producer = null;
    private IAmAChannelSync? _channel = null;

    public WhenRejectingMessageWithUnacceptableReasonShouldSendToInvalidChannel()
    {
        _messageGatewayProvider = new Paramore.Brighter.RMQ.Async.Tests.MessagingGateway.RmqNativeQuorumMessageGatewayProvider();
        _messageBuilder = new DefaultMessageBuilder();
    }

    public void Dispose()
    {
        _messageGatewayProvider.CleanUp(_producer, _channel, _sentMessages);
    }

    [Test]
    
    public async Task When_rejecting_message_with_unacceptable_reason_should_send_to_invalid_channel()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create,
            deadLetterRoutingKey: new RoutingKey($"{_publication.Topic!}.DLQ"),
            invalidMessageRoutingKey: new RoutingKey($"{_publication.Topic!}.Invalid"));

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var message = _messageBuilder.SetTopic(_publication.Topic!).Build();
        _sentMessages.Add(message);

        _producer.Send(message);

        // Act
        var received = _channel.Receive(TimeSpan.FromMilliseconds(4000));
        await Assert.That(received.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        var rejected = _channel.Reject(received, new MessageRejectionReason(RejectionReason.Unacceptable, "Test unacceptable message"));

        // Assert
        await Assert.That(rejected).IsTrue().Because("Reject should return true when the message was routed");

        // Assert
        var invalidMessage = new Message();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(60))
        {
            invalidMessage = _messageGatewayProvider.GetMessageFromInvalidChannel(_subscription);
            if (invalidMessage.Header.MessageType != MessageType.MT_NONE)
            {
                break;
            }
            Thread.Sleep(500);
        }

        await Assert.That(invalidMessage.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);
        await Assert.That(invalidMessage.Body.Value).IsEqualTo(message.Body.Value);

        var keys = _messageGatewayProvider.RejectionMetadataKeys;
        if (keys.StampsRejectionMetadata)
        {
            await Assert.That(invalidMessage.Header.Bag.ContainsKey(keys.OriginalTopic)).IsTrue();
            await Assert.That(invalidMessage.Header.Bag[keys.OriginalTopic].ToString()).IsEqualTo(_publication.Topic!.Value);
            await Assert.That(invalidMessage.Header.Bag.ContainsKey(keys.RejectionReason)).IsTrue();
            await Assert.That(invalidMessage.Header.Bag[keys.RejectionReason].ToString()).IsEqualTo(RejectionReason.Unacceptable.ToString());
        }

        // Assert
        var dlqMessage = _messageGatewayProvider.GetMessageFromDeadLetterQueue(_subscription);
        await Assert.That(dlqMessage.Header.MessageType).IsEqualTo(MessageType.MT_NONE);
    }}